#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按先序扩展序列建树，'#' 表示空子树 */
static void CreateBiTree(BiTree *T, const char *s, int *k) {
    if (s[*k] == '#') { (*k)++; *T = NULL; return; }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) { *T = NULL; printf("malloc failed\n"); return; }
    (*T)->data = s[*k];
    (*k)++;
    (*T)->lchild = NULL;
    (*T)->rchild = NULL;
    CreateBiTree(&(*T)->lchild, s, k);
    CreateBiTree(&(*T)->rchild, s, k);
}

static int ipow2(int e) {
    int v = 1, i;
    for (i = 0; i < e; i++) { v *= 2; }
    return v;
}

static void Count(const BiTree T, int *n0, int *n1, int *n2, int *depth) {
    int dl = 0, dr = 0;
    if (T == NULL) { *depth = 0; return; }
    if (T->lchild == NULL && T->rchild == NULL) { (*n0)++; }
    else if (T->lchild == NULL || T->rchild == NULL) { (*n1)++; }
    else { (*n2)++; }
    Count(T->lchild, n0, n1, n2, &dl);
    Count(T->rchild, n0, n1, n2, &dr);
    *depth = (dl > dr ? dl : dr) + 1;
}

static void Destroy(BiTree T) {
    if (T == NULL) { return; }
    Destroy(T->lchild);
    Destroy(T->rchild);
    free(T);
}

int main(void) {
    const char *cases[2];
    int t;
    cases[0] = "ABD##E##CF##G##";
    cases[1] = "A#CD###";

    for (t = 0; t < 2; t++) {
        BiTree T = NULL;
        int k = 0, n0 = 0, n1 = 0, n2 = 0, depth = 0, total;
        CreateBiTree(&T, cases[t], &k);
        Count(T, &n0, &n1, &n2, &depth);
        total = n0 + n1 + n2;
        printf("先序扩展序列：%s\n", cases[t]);
        printf("  n0=%d n1=%d n2=%d 总结点=%d 深度=%d\n", n0, n1, n2, total, depth);
        printf("  性质3：n0 = n2 + 1 → %d = %d + 1 → %s\n",
               n0, n2, (n0 == n2 + 1) ? "成立" : "不成立");
        printf("  性质2：结点数 %d <= 2^%d - 1 = %d → %s\n\n",
               total, depth, ipow2(depth) - 1,
               (total <= ipow2(depth) - 1) ? "成立" : "不成立");
        Destroy(T);
    }
    return 0;
}

