/* floor(log2 n)，用整数循环实现，避免依赖 libm */
static int floorLog2(int n) {
    int k = 0;
    while (n > 1) { n /= 2; k++; }
    return k;
}

static int ipow2(int e) {
    int v = 1, i;
    for (i = 0; i < e; i++) { v *= 2; }
    return v;
}

int main(void) {
    int n = 12, i, k, depth;

    printf("完全二叉树：n = %d，编号 1..%d\n\n", n, n);
    printf("%-5s%-9s%-9s%-9s%-8s%-8s\n",
           "i", "parent", "lchild", "rchild", "lsib", "rsib");
    for (i = 1; i <= n; i++) {
        int p  = (i == 1) ? 0 : i / 2;
        int lc = (2 * i > n) ? 0 : 2 * i;
        int rc = (2 * i + 1 > n) ? 0 : 2 * i + 1;
        int ls = (i == 1 || i % 2 == 1) ? 0 : i - 1;
        int rs = (i == n || i % 2 == 0) ? 0 : i + 1;
        printf("%-5d%-9d%-9d%-9d%-8d%-8d\n", i, p, lc, rc, ls, rs);
    }

