    printf("\n性质4：深度 = floor(log2(%d)) + 1 = %d\n", n, depth);
    printf("性质1：各层最多结点数 → ");
    for (k = 1; k <= depth; k++) { printf("L%d<=%d  ", k, ipow2(k - 1)); }
    printf("\n性质2：深度 %d 的二叉树最多 %d 个结点\n", depth, ipow2(depth) - 1);
