#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

static void CreateBiTree(BiTree *T, const char *s, int *k) {
    if (s[*k] == '#') { (*k)++; *T = NULL; return; }
    *T = (BiTNode *)malloc(sizeof(BiTNode));
    if (*T == NULL) { *T = NULL; printf("malloc failed\n"); return; }
    (*T)->data = s[*k];
    (*k)++;
    (*T)->lchild = NULL;
    (*T)->rchild = NULL;
    CreateBiTree(&(*T)->lchild, s, k);
    CreateBiTree(&(*T)->rchild, s, k);
}

/* nulls 统计空指针个数，即空链域数 */
static void Stat(const BiTree T, int *nodes, int *leaves, int *nulls) {
    if (T == NULL) { (*nulls)++; return; }
    (*nodes)++;
    if (T->lchild == NULL && T->rchild == NULL) { (*leaves)++; }
    Stat(T->lchild, nodes, leaves, nulls);
    Stat(T->rchild, nodes, leaves, nulls);
}

static void Destroy(BiTree T) {
    if (T == NULL) { return; }
    Destroy(T->lchild);
    Destroy(T->rchild);
    free(T);
}

int main(void) {
    const char *pre = "ABDH##I##EJ###CF##G##";
    BiTree T = NULL;
    int k = 0, nodes = 0, leaves = 0, nulls = 0;

    CreateBiTree(&T, pre, &k);
    Stat(T, &nodes, &leaves, &nulls);

    printf("先序扩展序列：%s\n", pre);
    printf("结点数 n = %d，叶子数 = %d\n", nodes, leaves);
    printf("链域总数 = 2n = %d\n", 2 * nodes);
    printf("实测空链域 = %d，公式 n+1 = %d，%s\n",
           nulls, nodes + 1, (nulls == nodes + 1) ? "吻合" : "不吻合");

    Destroy(T);
    return 0;
}

