#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

/* 按带空子树标记 `#` 的先序串建二叉树，i 为扫描位置 */
static void CreateBiTree(BiTree *T, const char *s, size_t *i)
{
    if (s[*i] == '#') { (*i)++; *T = NULL; return; }
    *T = (BiTree)malloc(sizeof(BiTNode));
    if (*T == NULL) { perror("malloc"); exit(1); }
    (*T)->data = s[*i];
    (*i)++;
    CreateBiTree(&((*T)->lchild), s, i);
    CreateBiTree(&((*T)->rchild), s, i);
}

static void PreOrder(BiTree T)
{
    if (T == NULL) return;
    printf("%c ", T->data);
    PreOrder(T->lchild);
    PreOrder(T->rchild);
}

static void InOrder(BiTree T)
{
    if (T == NULL) return;
    InOrder(T->lchild);
    printf("%c ", T->data);
    InOrder(T->rchild);
}

static void PostOrder(BiTree T)
{
    if (T == NULL) return;
    PostOrder(T->lchild);
    PostOrder(T->rchild);
    printf("%c ", T->data);
}

/* 层次遍历：用数组模拟队列 */
static void LevelOrder(BiTree T)
{
    BiTree q[64];
    int front = 0, rear = 0;
    if (T == NULL) return;
    q[rear++] = T;
    while (front < rear) {
        BiTree p = q[front++];
        printf("%c ", p->data);
        if (p->lchild != NULL) q[rear++] = p->lchild;
        if (p->rchild != NULL) q[rear++] = p->rchild;
    }
}

static void FreeBiTree(BiTree T)
{
    if (T == NULL) return;
    FreeBiTree(T->lchild);
    FreeBiTree(T->rchild);
    free(T);
}

/* 由先序 pre 与中序 in 重建，把后序序列写入 out */
static void Rebuild(const char *pre, const char *in, char *out, size_t *k)
{
    size_t n = strlen(pre), i = 0;
    char lp[32], li[32], rp[32], ri[32];
    if (n == 0) return;
    while (in[i] != pre[0]) i++;            /* 在中序中定位根 */
    memcpy(lp, pre + 1, i);       lp[i] = '\0';
    memcpy(li, in, i);            li[i] = '\0';
    memcpy(rp, pre + 1 + i, n - 1 - i); rp[n - 1 - i] = '\0';
    memcpy(ri, in + i + 1, n - 1 - i);  ri[n - 1 - i] = '\0';
    Rebuild(lp, li, out, k);                /* 左子树 */
    Rebuild(rp, ri, out, k);                /* 右子树 */
    out[(*k)++] = pre[0];                   /* 根最后输出 → 后序 */
}

int main(void)
{
    BiTree T = NULL;
    size_t i = 0, k = 0;
    char post[32];

    CreateBiTree(&T, "ABD##E##CF##G##", &i);

    printf("先序: "); PreOrder(T);   printf("\n");
    printf("中序: "); InOrder(T);    printf("\n");
    printf("后序: "); PostOrder(T);  printf("\n");
    printf("层次: "); LevelOrder(T); printf("\n");

    Rebuild("ABDECFG", "DBEAFCG", post, &k);
    post[k] = '\0';
    printf("由先序+中序重建得到的后序: %s\n", post);

    FreeBiTree(T);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
    int ltag, rtag;              /* 0 = 孩子指针；1 = 线索 */
} BiTNode, *BiTree;

static BiTree NewNode(char c)
{
    BiTree p = (BiTree)malloc(sizeof(BiTNode));
    if (p == NULL) { perror("malloc"); exit(1); }
    p->data = c;
    p->lchild = p->rchild = NULL;
    p->ltag = p->rtag = 0;
    return p;
}

static BiTree BuildDemo(void)    /* A(B(D,E), C(F,G)) */
{
    BiTree a = NewNode('A'), b = NewNode('B'), c = NewNode('C');
    BiTree d = NewNode('D'), e = NewNode('E');
    BiTree f = NewNode('F'), g = NewNode('G');
    a->lchild = b; a->rchild = c;
    b->lchild = d; b->rchild = e;
    c->lchild = f; c->rchild = g;
    return a;
}

static void InOrderByStack(BiTree T)
{
    BiTree stack[64];
    int top = -1;
    BiTree p = T;
    while (p != NULL || top >= 0) {
        while (p != NULL) { stack[++top] = p; p = p->lchild; }
        p = stack[top--];
        printf("%c ", p->data);
        p = p->rchild;
    }
}

static BiTNode *pre;             /* 中序前驱，线索化前置 NULL */

static void InThreading(BiTree p)
{
    if (p == NULL) return;
    InThreading(p->lchild);
    if (p->lchild == NULL) { p->ltag = 1; p->lchild = pre; }
    if (pre != NULL && pre->rchild == NULL) {
        pre->rtag = 1;
        pre->rchild = p;
    }
    pre = p;
    InThreading(p->rchild);
}

static void InOrderThr(BiTree T) /* 免递归免栈的中序遍历 */
{
    BiTree p = T;
    while (p != NULL) {
        while (p->ltag == 0) p = p->lchild;      /* 找最左下结点 */
        printf("%c ", p->data);
        while (p->rtag == 1 && p->rchild != NULL) {
            p = p->rchild;                       /* 沿后继线索走 */
            printf("%c ", p->data);
        }
        p = p->rchild;                           /* 进入右子树 */
    }
}

static void FreeThr(BiTree T)    /* tag==1 的指针不可再递归 */
{
    if (T == NULL) return;
    if (T->ltag == 0) FreeThr(T->lchild);
    if (T->rtag == 0) FreeThr(T->rchild);
    free(T);
}

int main(void)
{
    BiTree T = BuildDemo();

    printf("非递归中序: ");
    InOrderByStack(T);
    printf("\n");

    pre = NULL;
    InThreading(T);
    printf("线索中序  : ");
    InOrderThr(T);
    printf("\n");

    FreeThr(T);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned int weight;
    unsigned int parent, lchild, rchild;
} HTNode, *HuffmanTree;

/* 在 HT[1..end] 中选 parent==0 且权值最小的两个结点 */
static void Select(HuffmanTree HT, int end, int *s1, int *s2)
{
    int i, min1 = -1, min2 = -1;
    for (i = 1; i <= end; i++) {
        if (HT[i].parent != 0) continue;
        if (min1 == -1 || HT[i].weight < HT[min1].weight) {
            min2 = min1;
            min1 = i;
        } else if (min2 == -1 || HT[i].weight < HT[min2].weight) {
            min2 = i;
        }
    }
    *s1 = min1;
    *s2 = min2;
}

static void HuffmanBuild(HuffmanTree HT, const unsigned int *w, int n)
{
    int m = 2 * n - 1, i, s1, s2;
    for (i = 1; i <= m; i++) {
        HT[i].weight = (i <= n) ? w[i - 1] : 0u;
        HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        Select(HT, i - 1, &s1, &s2);
        HT[s1].parent = (unsigned int)i;
        HT[s2].parent = (unsigned int)i;
        HT[i].lchild = (unsigned int)s1;
        HT[i].rchild = (unsigned int)s2;
        HT[i].weight = HT[s1].weight + HT[s2].weight;
    }
}

/* 方法一：按定义，对叶子求 Σ(w × 深度) */
static unsigned int WPL_ByLeaf(HuffmanTree HT, int n)
{
    unsigned int sum = 0;
    int i, len, p;
    for (i = 1; i <= n; i++) {
        len = 0;
        for (p = (int)HT[i].parent; p != 0; p = (int)HT[p].parent) len++;
        sum += HT[i].weight * (unsigned int)len;
    }
    return sum;
}

/* 方法二：WPL = 所有内部结点的权值之和 */
static unsigned int WPL_ByInternal(HuffmanTree HT, int n)
{
    unsigned int sum = 0;
    int i;
    for (i = n + 1; i <= 2 * n - 1; i++) sum += HT[i].weight;
    return sum;
}

int main(void)
{
    const unsigned int w[8] = { 5, 29, 7, 8, 14, 23, 3, 11 };
    int n = 8, i;
    HuffmanTree HT = (HuffmanTree)malloc((size_t)(2 * n) * sizeof(HTNode));
    if (HT == NULL) { perror("malloc"); return 1; }

    HuffmanBuild(HT, w, n);

    printf("合并过程:\n");
    for (i = n + 1; i <= 2 * n - 1; i++)
        printf("  结点%2d = %2u + %2u = %3u\n", i,
               HT[HT[i].lchild].weight, HT[HT[i].rchild].weight, HT[i].weight);

    printf("按叶子求 WPL       = %u\n", WPL_ByLeaf(HT, n));
    printf("按内部结点求 WPL   = %u\n", WPL_ByInternal(HT, n));

    free(HT);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned int weight;
    unsigned int parent, lchild, rchild;
} HTNode, *HuffmanTree;

static void Select(HuffmanTree HT, int end, int *s1, int *s2)
{
    int i, min1 = -1, min2 = -1;
    for (i = 1; i <= end; i++) {
        if (HT[i].parent != 0) continue;
        if (min1 == -1 || HT[i].weight < HT[min1].weight) {
            min2 = min1;
            min1 = i;
        } else if (min2 == -1 || HT[i].weight < HT[min2].weight) {
            min2 = i;
        }
    }
    *s1 = min1;
    *s2 = min2;
}

static void HuffmanCoding(HuffmanTree HT, int n)
{
    char *cd = (char *)malloc((size_t)n * sizeof(char));
    int i, start, p;
    unsigned int total = 0, sumw = 0;

    if (cd == NULL) { perror("malloc"); exit(1); }
    cd[n - 1] = '\0';

    for (i = 1; i <= n; i++) {
        start = n - 1;
        /* 从叶子向上回溯：是父亲的左孩子记 0，右孩子记 1 */
        for (p = (int)HT[i].parent; p != 0; p = (int)HT[p].parent)
            cd[--start] = (HT[p].lchild == (unsigned int)i) ? '0' : '1';
        printf("  权值 %2u -> 编码 %s (码长 %d)\n",
               HT[i].weight, &cd[start], n - 1 - start);
        total += HT[i].weight * (unsigned int)(n - 1 - start);
        sumw  += HT[i].weight;
    }

    printf("哈夫曼编码总位数     = %u\n", total);
    printf("等长编码(3 bit)总位数 = %u\n", 3u * sumw);
    printf("平均码长             = %.2f 位/字符\n",
           (double)total / (double)sumw);
    free(cd);
}

int main(void)
{
    const unsigned int w[8] = { 5, 29, 7, 8, 14, 23, 3, 11 };
    int n = 8, m = 2 * n - 1, i, s1, s2;
    HuffmanTree HT = (HuffmanTree)malloc(((size_t)m + 1) * sizeof(HTNode));
    if (HT == NULL) { perror("malloc"); return 1; }

    for (i = 1; i <= m; i++) {
        HT[i].weight = (i <= n) ? w[i - 1] : 0u;
        HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    }
    for (i = n + 1; i <= m; i++) {
        Select(HT, i - 1, &s1, &s2);
        HT[s1].parent = (unsigned int)i;
        HT[s2].parent = (unsigned int)i;
        HT[i].lchild  = (unsigned int)s1;
        HT[i].rchild  = (unsigned int)s2;
        HT[i].weight  = HT[s1].weight + HT[s2].weight;
    }

    HuffmanCoding(HT, n);

    free(HT);
    return 0;
}
